using SuperMetroid.Core;

namespace SuperMetroid.AssetExtraction.Lists;

/// <summary>
/// The private members of <see cref="SuperMetroid.AssetExtraction.Lists.ListIdentity"/> checks name (#2570), each an extension member of the
/// same name and signature reaching the private member through <see cref="PrivateState"/>, so checks name them as the
/// owner's own code does and production keeps them private. Generated by the architecture audit's
/// <c>--fix-test-only-members</c> and the reachability prune.
/// </summary>
internal static class ListIdentityPrivateAccess
{
    /// <summary>The private static members checks name.</summary>
    extension(global::SuperMetroid.AssetExtraction.Lists.ListIdentity)
    {
        /// <summary>The private method <c>Mix</c>, invoked by name.</summary>
        internal static int Mix(int high, int low) =>
            PrivateState.InvokeStatic<int>(typeof(global::SuperMetroid.AssetExtraction.Lists.ListIdentity), "Mix", [typeof(int), typeof(int)], new object?[] { high, low });

        /// <summary>The private method <c>Spread</c>, invoked by name.</summary>
        internal static int Spread(int weight) =>
            PrivateState.InvokeStatic<int>(typeof(global::SuperMetroid.AssetExtraction.Lists.ListIdentity), "Spread", [typeof(int)], new object?[] { weight });
    }

    /// <summary>The private extension methods checks call on their receiver.</summary>
    extension(global::SuperMetroid.AssetExtraction.Lists.ListLayout self)
    {
        /// <summary>The private extension method <c>Weight</c>, invoked by name.</summary>
        internal int Weight() =>
            PrivateState.InvokeStatic<int>(typeof(global::SuperMetroid.AssetExtraction.Lists.ListIdentity), "Weight", [typeof(global::SuperMetroid.AssetExtraction.Lists.ListLayout)], new object?[] { self });
    }
}
